"""Parse a cron expression into the sets of values each of its five fields matches."""

from dataclasses import dataclass

MONTH_NAMES = {
    name: i
    for i, name in enumerate(
        "JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split(), start=1
    )
}
DAY_NAMES = {
    name: i for i, name in enumerate("SUN MON TUE WED THU FRI SAT".split())
}

MACROS = {
    "@hourly": "0 * * * *",
    "@daily": "0 0 * * *",
    "@weekly": "0 0 * * 0",
    "@monthly": "0 0 1 * *",
    "@yearly": "0 0 1 1 *",
}


class CronError(ValueError):
    """A cron expression that cannot be parsed. The message names the bad field."""


@dataclass(frozen=True)
class Field:
    name: str
    low: int
    high: int
    names: dict[str, int] | None = None
    # A field left as "*" is unrestricted; day-of-month and day-of-week use that
    # to decide whether their match is an OR or an AND.
    restricted: bool = False


FIELDS = (
    Field("minute", 0, 59),
    Field("hour", 0, 23),
    Field("day-of-month", 1, 31),
    Field("month", 1, 12, MONTH_NAMES),
    Field("day-of-week", 0, 7, DAY_NAMES),
)


@dataclass(frozen=True)
class CronExpr:
    minutes: frozenset[int]
    hours: frozenset[int]
    days_of_month: frozenset[int]
    months: frozenset[int]
    days_of_week: frozenset[int]
    dom_restricted: bool
    dow_restricted: bool


def parse(expr: str) -> CronExpr:
    """Parse `expr` into a CronExpr, or raise CronError naming the bad field."""
    text = expr.strip()
    if text.startswith("@"):
        expanded = MACROS.get(text.lower())
        if expanded is None:
            raise CronError(
                f"unknown macro {text!r}: expected one of "
                + ", ".join(sorted(MACROS))
            )
        text = expanded

    fields = text.split()
    if len(fields) != 5:
        raise CronError(
            f"expected 5 fields (minute hour day-of-month month day-of-week), "
            f"got {len(fields)}: {expr!r}"
        )

    values = [_parse_field(spec, field) for spec, field in zip(fields, FIELDS)]
    dow = frozenset(0 if v == 7 else v for v in values[4])
    return CronExpr(
        minutes=values[0],
        hours=values[1],
        days_of_month=values[2],
        months=values[3],
        days_of_week=dow,
        dom_restricted=fields[2] != "*",
        dow_restricted=fields[4] != "*",
    )


def _parse_field(spec: str, field: Field) -> frozenset[int]:
    values: set[int] = set()
    if spec == "":
        raise CronError(f"{field.name}: empty field")
    for part in spec.split(","):
        values |= _parse_part(part, field, spec)
    return frozenset(values)


def _parse_part(part: str, field: Field, spec: str) -> set[int]:
    body, sep, step_text = part.partition("/")
    step = 1
    if sep:
        step = _to_int(step_text, field, spec)
        if step < 1:
            raise CronError(f"{field.name}: step must be 1 or more in {spec!r}")

    if body == "*":
        low, high = field.low, field.high
    elif "-" in body[1:] or (body.startswith("-") and False):
        start_text, _, end_text = body.partition("-")
        low = _value(start_text, field, spec)
        high = _value(end_text, field, spec)
        if low > high:
            raise CronError(
                f"{field.name}: range {body!r} runs backwards in {spec!r}"
            )
    else:
        low = high = _value(body, field, spec)
        if not sep:
            return {low}

    return set(range(low, high + 1, step))


def _value(text: str, field: Field, spec: str) -> int:
    if field.names is not None:
        named = field.names.get(text.strip().upper())
        if named is not None:
            return named
    value = _to_int(text, field, spec)
    if not field.low <= value <= field.high:
        raise CronError(
            f"{field.name}: {value} out of range "
            f"{field.low}-{field.high} in {spec!r}"
        )
    return value


def _to_int(text: str, field: Field, spec: str) -> int:
    try:
        return int(text)
    except ValueError:
        raise CronError(f"{field.name}: {text!r} is not a number in {spec!r}") from None
