"""Turn a cron expression into one plain-English line."""

from .parser import CronExpr, parse

DAY_WORDS = ("Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday")
MONTH_WORDS = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


def describe(expr: str | CronExpr) -> str:
    """One sentence saying when `expr` runs."""
    cron = parse(expr) if isinstance(expr, str) else expr
    parts = [_when(cron), _days(cron)]
    if len(cron.months) < 12:
        parts.append("in " + _join(MONTH_WORDS[m - 1] for m in sorted(cron.months)))
    return ", ".join(parts) + "."


def _when(cron: CronExpr) -> str:
    every_hour = len(cron.hours) == 24
    if every_hour:
        if len(cron.minutes) == 60:
            return "Every minute"
        step = _step(sorted(cron.minutes), 60)
        if step:
            return f"Every {step} minutes"
        return "At minute " + _join(str(m) for m in sorted(cron.minutes)) + " of every hour"
    times = [
        f"{h:02d}:{m:02d}" for h in sorted(cron.hours) for m in sorted(cron.minutes)
    ]
    if len(times) <= 4:
        return "At " + _join(times)
    return (
        "At minute " + _join(str(m) for m in sorted(cron.minutes))
        + " of hour " + _join(str(h) for h in sorted(cron.hours))
    )


def _days(cron: CronExpr) -> str:
    clauses = []
    if cron.dom_restricted:
        clauses.append(
            "on the " + _join(_ordinal(d) for d in sorted(cron.days_of_month))
            + " of the month"
        )
    if cron.dow_restricted:
        clauses.append("on " + _run_or_list(sorted(cron.days_of_week)))
    if not clauses:
        return "every day"
    # Both restricted means either one is enough to fire, so say "or".
    return " or ".join(clauses)


def _run_or_list(days: list[int]) -> str:
    if len(days) > 2 and days == list(range(days[0], days[-1] + 1)):
        return f"{DAY_WORDS[days[0]]} through {DAY_WORDS[days[-1]]}"
    return _join(DAY_WORDS[d] for d in days)


def _step(values: list[int], size: int) -> int | None:
    """The step of `values` if they are 0, n, 2n, ... across the whole field."""
    if len(values) < 2 or values[0] != 0:
        return None
    step = values[1]
    if values == list(range(0, size, step)):
        return step
    return None


def _ordinal(n: int) -> str:
    if 11 <= n % 100 <= 13:
        return f"{n}th"
    return f"{n}{ {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th') }"


def _join(items) -> str:
    items = list(items)
    if len(items) == 1:
        return items[0]
    return ", ".join(items[:-1]) + " and " + items[-1]
