"""The `cron` command line: next, describe, match."""

import argparse
import sys
from datetime import datetime, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from .describe import describe
from .parser import CronError
from .schedule import matches, next_times

UTC = timezone.utc


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="cron", description="Parse cron expressions and project future run times."
    )
    sub = parser.add_subparsers(dest="command", required=True)

    nxt = sub.add_parser("next", help="print the next run times")
    nxt.add_argument("expr", help="a cron expression, e.g. '0 9 * * 1-5'")
    nxt.add_argument("--count", type=int, default=1, help="how many times to print")
    nxt.add_argument("--from", dest="start", help="ISO 8601 start time (default: now)")
    nxt.add_argument("--tz", default="UTC", help="IANA zone name (default: UTC)")

    desc = sub.add_parser("describe", help="say in English when it runs")
    desc.add_argument("expr")

    match = sub.add_parser("match", help="exit 0 if it would run at that time")
    match.add_argument("expr")
    match.add_argument("when", help="ISO 8601 timestamp")
    match.add_argument("--tz", default="UTC", help="IANA zone name (default: UTC)")

    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        return _dispatch(args)
    except (CronError, ValueError) as exc:
        print(f"cron: {exc}", file=sys.stderr)
        return 2


def _dispatch(args: argparse.Namespace) -> int:
    if args.command == "describe":
        print(describe(args.expr))
        return 0

    tz = _zone(args.tz)
    if args.command == "next":
        if args.count < 1:
            raise ValueError("--count must be 1 or more")
        start = _timestamp(args.start, tz) if args.start else datetime.now(tz)
        for run in next_times(args.expr, start, args.count, tz):
            print(run.isoformat())
        return 0

    return 0 if matches(args.expr, _timestamp(args.when, tz), tz) else 1


def _zone(name: str) -> ZoneInfo | timezone:
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError) as exc:
        raise ValueError(f"unknown time zone {name!r}: {exc}") from None


def _timestamp(text: str, tz: ZoneInfo | timezone) -> datetime:
    try:
        when = datetime.fromisoformat(text)
    except ValueError:
        raise ValueError(f"not an ISO 8601 timestamp: {text!r}") from None
    return when if when.tzinfo else when.replace(tzinfo=tz)


if __name__ == "__main__":
    raise SystemExit(main())
